export async function reactivateMember(
  orgId: OrgId,
  memberId: MemberId,
  grant: { role: Role; invitedBy: UserId; joinedAt: IsoTimestamp },
): Promise<Member> {
  const row = getDb()
    .update(members)
    .set({
      ...restorePatch(new Date(grant.joinedAt)),
      status: "active",
      role: grant.role,
      invitedBy: grant.invitedBy,
      joinedAt: grant.joinedAt,
    })
    .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
    .returning()
    .get();

